    for i in range(1, len(nums)):
        cur = cur + 1 if nums[i] > nums[i-1] else 1
        best = max(best, cur)
    return best

def find_length_of_lcis(nums):
    best = l = 1
    for r in range(1, len(nums)):
        if nums[r] <= nums[r-1]:
            l = r
        best = max(best, r - l + 1)
    return best

def find_length_of_lcis(nums):
    breaks = [0] + [i for i in range(1, len(nums)) if nums[i] <= nums[i-1]] + [len(nums)]
    return max(breaks[k+1] - breaks[k] for k in range(len(breaks)-1))

def find_shortest_sub_array(nums):
    first, last, cnt = {}, {}, {}
    best = len(nums)
    for i, x in enumerate(nums):
        if x not in first: first[x] = i
        last[x] = i
        cnt[x] = cnt.get(x, 0) + 1
    d = max(cnt.values())
    for x in cnt:
        if cnt[x] == d:
            best = min(best, last[x] - first[x] + 1)
    return best

def find_shortest_sub_array(nums):
    from collections import Counter
    freq = Counter(nums)
    d = max(freq.values())
    return min(len(nums) - nums[::-1].index(x) - nums.index(x) for x in freq if freq[x] == d)

def find_shortest_sub_array(nums):
    from collections import Counter
    total = Counter(nums)
    d = max(total.values())
    best = len(nums)
    for i in range(len(nums)):
        cnt = {}
        for j in range(i, len(nums)):
            cnt[nums[j]] = cnt.get(nums[j], 0) + 1
            if max(cnt.values()) == d:
                best = min(best, j - i + 1)
                break
    return best

def pivot_index(nums):
    for i in range(len(nums)):
        if sum(nums[:i]) == sum(nums[i+1:]): return i
    return -1

def dominant_index(nums):
    mx = max(nums)
    if any(x*2 > mx for x in nums if x != mx): return -1
    return nums.index(mx)

def dominant_index(nums):
    if len(nums) == 1:
        return 0
    mx = second = -10**9
    mx_i = 0
    for i, x in enumerate(nums):
        if x > mx:
            second, mx, mx_i = mx, x, i
        elif x > second and x != mx:
            second = x
    if mx < 2 * second:
        return -1
    return mx_i if nums.count(mx) == 1 else -1

