def is_monotonic(nums):
    inc = dec = True
    for i in range(1, len(nums)):
        if nums[i] < nums[i-1]: inc = False
        if nums[i] > nums[i-1]: dec = False
    return inc or dec

def max_subarray_sum_circular(nums):
    total = sum(nums)
    cur_max = best_max = nums[0]
    cur_min = best_min = nums[0]
    for x in nums[1:]:
        cur_max = max(x, cur_max + x); best_max = max(best_max, cur_max)
        cur_min = min(x, cur_min + x); best_min = min(best_min, cur_min)
    return best_max if best_max < 0 else max(best_max, total - best_min)

def kadane(a):
    best = cur = a[0]
    for x in a[1:]:
        cur = max(x, cur + x); best = max(best, cur)
    return best
def max_subarray_sum_circular(nums):
    best = kadane(nums)
    if best < 0: return best
    best_mirror = kadane([-x for x in nums])
    return max(best, sum(nums) + best_mirror)

def largest_sum_after_k_negations(nums, k):
    nums.sort()
    for i in range(len(nums)):
        if k == 0: break
        if nums[i] < 0:
            nums[i] = -nums[i]; k -= 1
    if k % 2 == 1:
        nums.sort()
        nums[0] = -nums[0]
    return sum(nums)

def largest_sum_after_k_negations(nums, k):
    nums.sort(key=abs)
    for i in range(len(nums)):
        if nums[i] < 0 and k:
            nums[i] = -nums[i]; k -= 1
    if k % 2 == 1:
        nums[0] = -nums[0]
    return sum(nums)

def largest_sum_after_k_negations(nums, k):
    for _ in range(k):
        i = nums.index(min(nums))
        nums[i] = -nums[i]
    return sum(nums)

def gcd_of_strings(str1, str2):
    if str1 + str2 != str2 + str1: return ''
    for l in range(min(len(str1), len(str2)), 0, -1):
        if len(str1) % l == 0 and len(str2) % l == 0:
            cand = str1[:l]
            if cand * (len(str1)//l) == str1 and cand * (len(str2)//l) == str2:
                return cand
    return ''

