def are_almost_equal(s1, s2):
    diff = [i for i in range(len(s1)) if s1[i] != s2[i]]
    return len(diff) == 0 or (len(diff) == 2 and s1[diff[0]] == s2[diff[1]] and s1[diff[1]] == s2[diff[0]])

def are_almost_equal(s1, s2):
    a = b = None
    for i, (x, y) in enumerate(zip(s1, s2)):
        if x == y: continue
        if a is None:
            a = i
        elif b is None:
            b = i
        else:
            return False
    return a is None or (b is not None and s1[a] == s2[b] and s1[b] == s2[a])

